export function occupationText(language:ScenarioLanguage){
 const [fs,as]=vocabulary[language].map(x=>x.split("|")),words=actionWords[language].split("|");
 if(fs.length!==fields.length||as.length!==artifacts.length||words.length!==7)throw new Error("occupation_locale_incomplete:"+language);
 return {labels:Object.fromEntries(fields.map((k,i)=>[k,fs[i]])),artifacts:Object.fromEntries(artifacts.map((k,i)=>[k,as[i]])),
  compare:words[0],ask:words[1],trace:words[2],uncertain:words[3],authority:words[4],delay:words[5],boundary:words[6]};
}
